<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useWorkspace } from '../stores/workspace'
import ProductTable from '../components/ProductTable.vue'
const route = useRoute(), router = useRouter(), store = useWorkspace()
const selected = ref(null), comment = ref(''), query = ref(''), category = ref('全部'), busy = ref(false)
const key = computed(() => route.meta.key)
const stage = computed(() => key.value === 'candidates' ? 'second' : 'first')
const displayed = computed(() => (stage.value === 'first' ? store.pool : store.candidates).filter(p => `${p.title}${p.platform_product_id}${p.category}`.toLowerCase().includes(query.value.toLowerCase()) && (category.value === '全部' || p.category === category.value)))
watch(key, () => { query.value = ''; category.value = '全部'; selected.value = null })
function openReview(product) { selected.value = product; comment.value = '' }
async function decide(approved) { if (!approved && !comment.value.trim()) { store.error = '驳回请填写意见。'; return } busy.value = true; if (await store.review(selected.value.task_id, approved, comment.value)) selected.value = null; busy.value = false }
const subtitles = { dashboard:'欢迎回来，在这里掌握选品与内容的整体进展。', pool:'初次人工核验通过后，商品进入候选池。', candidates:'再次人工核验通过后，才可以创建内容任务。', content:'基于复核通过的候选商品创建内容任务。', review:'内容仍需经过人工审核，审核功能待实现。', listing:'上架方式暂未确定，本页仅预留任务入口。', rules:'将利润公式、汇率与筛选条件交给运营配置。', audit:'可编辑的审核规则，支持版本管理与回滚。', crawl:'仅规划公开数据采集；合规批准前默认关闭。', logs:'查看当前演示环境的操作记录。' }
const placeholder = { content:['模型服务未配置','内容生成适配器与任务执行待实现，列表仅展示复核创建的待处理任务。'], review:['审核功能待实现','不会对任何内容作出自动或人工审核结论。'], listing:['上架方式待确认','不调用亚马逊，也不模拟真实上架成功。'], rules:['筛选规则配置待实现','利润公式、汇率、筛选阈值的编辑、版本发布与回滚尚未接入。'], audit:['审核逻辑配置待实现','审核逻辑的编辑、版本发布、回滚与审计尚未接入。'], crawl:['采集能力未启用','平台条款、robots、验证码、反爬、风控与数据合规需确认。'] }
</script>
<template>
  <div class="welcome"><div><div class="eyebrow">MERIDIAN / {{ key.toUpperCase() }}</div><h1>{{ route.meta.title }}</h1><p>{{ subtitles[key] }}</p></div><div class="btn-row"><button class="secondary" @click="store.refresh()">↻ 刷新数据</button><a v-if="key === 'dashboard'" class="primary" href="/prototype/index.html" target="_blank" rel="noopener" style="text-decoration:none">打开交互原型 ↗</a></div></div>
  <div class="notice warn">◉ &nbsp; 项目框架为演示环境：无真实登录、权限、采集、模型、侵权或上架对接；数据不可用于业务决策。</div>
  <div v-if="store.error" class="notice warn" role="alert">{{ store.error }}</div><div v-if="store.notice" class="notice" role="status">{{ store.notice }}</div>
  <div v-if="store.loading" class="card loading">正在加载演示数据…</div>
  <template v-else-if="key === 'dashboard'">
    <div class="stats"><div v-for="item in [['商品池',store.pool.length,'▧','待初核的示例商品'],['候选池',store.candidates.length,'◇','等待第二次人工核验'],['内容任务',store.jobs.length,'✦','仅创建任务，未生成内容'],['外部连接','—','↗','均未启用'] ]" :key="item[0]" class="card stat"><div class="stat-top">{{ item[0] }}<span class="stat-icon">{{ item[2] }}</span></div><strong>{{ item[1] }}</strong><small><em>●</em> {{ item[3] }}</small></div></div>
    <div class="grid"><section class="card panel"><div class="panel-head"><div><h2>选品概览</h2><p>示例趋势 · 仅用于界面展示</p></div><span class="badge gray">示意图</span></div><svg class="chart" viewBox="0 0 600 195" preserveAspectRatio="none" aria-label="示例趋势图"><defs><linearGradient id="chartGradient" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#63c8b4" stop-opacity=".22"/><stop offset="1" stop-color="#63c8b4" stop-opacity="0"/></linearGradient></defs><path d="M0 20H600M0 65H600M0 110H600M0 155H600" stroke="#eff2f4" fill="none"/><path d="M0 153 C60 140 75 150 120 125 S190 110 240 115 S300 77 360 88 S435 51 480 62 S550 35 600 27 L600 180 L0 180Z" fill="url(#chartGradient)"/><path d="M0 153 C60 140 75 150 120 125 S190 110 240 115 S300 77 360 88 S435 51 480 62 S550 35 600 27" fill="none" stroke="#42b5a0" stroke-width="3"/></svg><div class="chart-labels"><span>周一</span><span>周二</span><span>周三</span><span>周四</span><span>周五</span><span>周六</span><span>周日</span></div></section>
      <section class="card panel"><div class="panel-head"><div><h2>工作流程</h2><p>从发现好商品到准备上架</p></div><button class="link" @click="router.push('/pool')">查看详情 →</button></div><div class="flow"><div v-for="x in [['▧','选品分析','公开数据 → 货源匹配 → 利润及侵权校验','流程起点'],['◇','两阶段核验','商品池初核 → 候选池复核','人工参与'],['✦','商品内容生成','生成内容 → 可编辑审核逻辑','待模型配置'],['↗','人工审核与上架','人工终审 → 上架任务','方式待确认']]" :key="x[1]" class="flow-row"><div class="dot">{{ x[0] }}</div><div class="flow-text"><b>{{ x[1] }}</b><small>{{ x[2] }}</small></div><span class="badge blue">{{ x[3] }}</span></div></div></section></div>
    <section class="card panel"><div class="panel-head"><div><h2>最近待核验商品</h2><p>先从商品池开始，找到值得关注的好商品</p></div><button class="link" @click="router.push('/pool')">查看商品池 →</button></div><ProductTable :products="store.pool" stage="first" @review="openReview" /></section><div class="footnote">说明：所有数据均为虚构示例，不代表真实采集、侵权判断或业务指标。</div>
  </template>
  <template v-else-if="key === 'pool' || key === 'candidates'"><section class="card panel"><div class="panel-head"><div><h2>{{ key === 'pool' ? '待初核商品' : '待复核商品' }}</h2><p>共 {{ displayed.length }} 条示例记录</p></div><span class="badge blue">{{ key === 'pool' ? '第一阶段' : '第二阶段' }}</span></div><div class="toolbar"><input v-model="query" aria-label="搜索商品" placeholder="搜索商品名称、编号或类目"><select v-model="category" aria-label="商品类目"><option>全部</option><option>家居收纳</option><option>厨房用品</option><option>办公用品</option></select><button class="secondary" @click="query = ''; category = '全部'">重置</button></div><ProductTable :products="displayed" :stage="stage" @review="openReview" /></section></template>
  <template v-else-if="key === 'logs'"><section class="card panel"><div class="panel-head"><div><h2>操作记录</h2><p>只记录演示环境的核验操作</p></div></div><div v-if="!store.logs.length" class="empty">暂无操作记录</div><div v-for="log in store.logs" :key="log.id" style="border-bottom:1px solid #f1f3f5;padding:14px;color:#627487">◷ &nbsp; {{ log.action }} · {{ log.target }} · {{ log.detail || '无意见' }} <small>{{ log.created_at }}</small></div></section></template>
  <template v-else><section class="card panel"><div class="panel-head"><div><h2>{{ placeholder[key][0] }}</h2><p>{{ placeholder[key][1] }}</p></div><span class="badge amber">待实现</span></div><template v-if="key === 'content' && store.jobs.length"><div class="table-wrap"><table><thead><tr><th>任务编号</th><th>关联商品</th><th>状态</th></tr></thead><tbody><tr v-for="job in store.jobs" :key="job.id"><td>CJ-{{ job.id }}</td><td>{{ job.product_title }}</td><td><span class="badge blue">{{ job.status }} · 未生成</span></td></tr></tbody></table></div></template><div v-else class="empty">功能入口已预留，尚未接入真实业务</div><div v-if="key === 'rules'" class="notice">目标规则：单品毛利润或月总销售额任一满足；公式、汇率与阈值由运营配置。具体口径待确认。</div><div v-if="key === 'audit'" class="notice">目标能力：运营编辑审核规则，版本化、回滚与审计。具体发布权限待确认。</div><a href="/prototype/index.html" target="_blank" rel="noopener" class="link">在交互原型中体验此页面 →</a></section></template>
  <div v-if="selected" class="modal-bg" @click.self="selected = null"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="review-title"><h2 id="review-title">{{ key === 'candidates' ? '候选商品再次核验' : '商品初次核验' }}</h2><p><b>{{ selected.title }}</b> · {{ selected.platform_product_id }}<br>这是演示商品，核验仅更新本地演示数据库。</p><label for="review-comment">核验意见（驳回时必填）</label><input id="review-comment" v-model="comment" maxlength="1000" placeholder="输入核验意见"><div class="actions"><button class="secondary" @click="selected = null">取消</button><button class="secondary" :disabled="busy" @click="decide(false)">驳回</button><button class="primary" :disabled="busy" @click="decide(true)">核验通过</button></div></div></div>
</template>
